}

.sw-row-problems {
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--sw-error);
  font-size: 12px;
}

.sw-row-problem-warning {
  color: var(--sw-warning);
}

.sw-row-problem-info {
  color: var(--sw-info);
}

.sw-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}


.sw-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px 0;
}

.sw-row-head {
  display: flex;
  gap: var(--sw-gap);
  align-items: center;
}

.sw-row-label {
  flex: 1 1 auto;
  color: var(--sw-fg);
  font-weight: 600;
}

.sw-row-description,
.sw-row-note {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  margin: 0;
  overflow: hidden;
  color: var(--sw-muted);
  font-size: 12px;
}

.sw-row-description:hover,
.sw-row-note {
  -webkit-line-clamp: unset;
}

.sw-row-value {
  min-width: 0;
  font-family: var(--sw-mono);
  overflow-wrap: anywhere;
}

.sw-badge {
  padding: 0 6px;
  color: var(--sw-error);
  border: 1px solid var(--sw-error);
  border-radius: var(--sw-radius);
  font-size: 11px;
}

.sw-input {
  box-sizing: border-box;
  min-width: 0;
  padding: 4px 6px;
  color: var(--sw-fg);
  background: var(--sw-bg);
  border: 1px solid var(--sw-border);
  border-radius: var(--sw-radius);
  font: inherit;
}

.sw-widget-text .sw-input,
.sw-widget-enum .sw-input {
  width: 100%;
}

.sw-input[aria-invalid='true'] {
  border-color: var(--sw-error);
}

.sw-input:focus-visible,
.sw-btn:focus-visible {
  outline: 2px solid var(--sw-focus);
  outline-offset: 1px;
}

.sw-input:disabled {
  opacity: 0.7;
}

.sw-field-error {
  display: block;
  color: var(--sw-error);
  font-size: 12px;
}

.sw-field-error:empty {
  display: none;
}

.sw-list-items {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sw-list-item,
.sw-list-add {
  display: flex;
  gap: 4px;
  margin-top: 4px;
}

.sw-list-item .sw-input,
.sw-list-add .sw-input {
  flex: 1 1 0;
}

